/*
 * Held — control UI.
 *
 * Two modes:
 *   Simulator  the page runs the pattern engine locally (opened from a file, the dev server,
 *              or when no device answers). Settings persist in this browser (localStorage).
 *   Device     served by (or connected to) a Held controller. Edits are sent live to the device
 *              (POST /json/held) and mirrored in the local engine; "Save" stores them on the
 *              device. The 3D view can show the device's real LED output (WebSocket live view).
 */
(function () {
	'use strict';

	const S = window.HELD_SCHEMA;
	const $ = (id) => document.getElementById(id);
	const el = (tag, cls, txt) => { const e = document.createElement(tag); if (cls) e.className = cls; if (txt !== undefined) e.textContent = txt; return e; };
	const SIM_KEY = 'held.sim.v1';
	const IP_KEY = 'held.ip';
	const POLL_MS = 1000;
	const SEND_DEBOUNCE_MS = 150;
	const MAX_STRIPS = 4;
	const EXPR_HEAD = '(pieces, t, et, level) => ';

	const eng = new HeldEngine();
	let view = new HeldView3D($('view'));   // replaced by the WebGL view if three.js loads (start())
	const kymo = new HeldKymo($('kymo'));

	const app = {
		device: null,        // base URL ('' = same origin) when connected, null in simulator mode
		online: true,
		live: false,         // show the device's real LEDs instead of the local mirror
		ws: null,
		liveBufs: [],
		starts: [],          // global LED index where each device strip starts
		playing: true,
		timeScale: 1,
		bri: 128,
		autoApply: true,
		strips: [S.defaultStrip(0)],
		tab: 'heartbeat',
		dirty: false,
		pending: null,
		pendingTimer: 0,
		devState: null,
		devStateAt: 0,
		nowEls: []
	};

	// ------------------------------------------------------------------ utils
	function toast(msg) {
		const t = $('toast');
		t.textContent = msg;
		t.classList.add('show');
		clearTimeout(toast.tm);
		toast.tm = setTimeout(() => t.classList.remove('show'), 2200);
	}
	const hex = (c) => '#' + (c >>> 0).toString(16).padStart(6, '0');
	function fmt(v, def) {
		if (def.t !== 'f') return String(Math.round(v));
		const s = def.s || 0.01;
		return v.toFixed(s < 0.1 ? 2 : (s < 1 ? 1 : 0));
	}
	function popcount(m) { let n = 0; for (; m; m &= m - 1) n++; return n; }
	function defsOf(group) { return group === 'global' ? S.global : S.layerByKey[group].p; }

	function exportParams() {
		const out = {};
		for (const g in eng.params) {
			out[g] = {};
			for (const def of defsOf(g)) {
				const v = eng.params[g][def.k];
				out[g][def.k] = def.t === 'c' ? hex(v) : (Array.isArray(v) ? v.slice() : v);
			}
		}
		return out;
	}

	// ------------------------------------------------------------------ device link
	async function api(method, path, body, timeout) {
		const ctl = new AbortController();
		const tm = setTimeout(() => ctl.abort(), timeout || 3000);
		try {
			const r = await fetch((app.device || '') + path, {
				method: method, signal: ctl.signal,
				headers: body ? { 'Content-Type': 'application/json' } : undefined,
				body: body ? JSON.stringify(body) : undefined
			});
			if (!r.ok) throw new Error('HTTP ' + r.status);
			const j = await r.json();
			setOnline(true);
			return j;
		} catch (e) {
			if (app.device !== null) setOnline(false);
			return null;
		} finally {
			clearTimeout(tm);
		}
	}

	function send(obj) {
		if (app.device === null) return Promise.resolve(null);
		return api('POST', '/json/held', obj).then((j) => {
			if (j && j.v !== undefined) takeState(j);
			if (j && j.exprError) toast('Device rejected ' + j.exprError);
			return j;
		});
	}

	function queueParams(partial) {
		if (app.device === null) return;
		app.pending = app.pending || {};
		for (const g in partial) Object.assign(app.pending[g] = app.pending[g] || {}, partial[g]);
		clearTimeout(app.pendingTimer);
		app.pendingTimer = setTimeout(() => {
			const p = app.pending;
			app.pending = null;
			send({ params: p });
		}, SEND_DEBOUNCE_MS);
	}

	function setOnline(on) {
		if (app.probing || app.online === on) return;
		app.online = on;
		updateBadge();
		if (!on) toast('Lost connection to device');
	}

	function updateBadge() {
		const b = $('mode');
		if (app.device === null) { b.textContent = 'SIM'; b.className = 'badge'; b.title = 'Simulator: running the engine in this browser'; }
		else {
			b.textContent = app.online ? 'DEVICE' : 'OFFLINE';
			b.className = 'badge ' + (app.online ? 'dev' : 'off');
			b.title = app.device ? 'Connected to ' + app.device : 'Connected to this device';
		}
		$('srcBtn').hidden = app.device === null || !app.ws;
		$('saveNote').textContent = app.device === null
			? 'Simulator settings are kept in this browser automatically. Use Export / Import to move them to a device.'
			: 'Edits apply live; Save stores them on the device so they survive a reboot.';
	}

	// silently align piece state (no events): used when adopting the device's state
	function adoptMask(mask) {
		eng.mask = mask >>> 0;
		eng.count = popcount(eng.mask);
	}

	function takeState(j) {
		app.devState = j;
		app.devStateAt = performance.now();
		if (j.mask !== undefined && j.mask !== eng.mask) eng.setPieces(j.mask);   // mirror sensor-driven changes (and their events)
		if (j.playing !== undefined && j.playing !== app.playing) { app.playing = j.playing; updateTransport(); }
		if (j.timeScale !== undefined && j.timeScale !== app.timeScale) { app.timeScale = j.timeScale; updateTransport(); }
		if (j.autoApply !== undefined) app.autoApply = j.autoApply;
		if (j.bri !== undefined && j.bri !== app.bri) { app.bri = j.bri; $('bri').value = j.bri; }
		renderPieces();
	}

	function takeFull(j) {
		if (j.params) eng.setParams(j.params);
		if (j.strips && j.strips.length) {
			app.strips = j.strips.map((s, i) => HeldEngine.sanitizeStrip(s, i));
			let acc = 0;
			app.starts = j.strips.map((s, i) => { const st = s.start !== undefined ? s.start : acc; acc = st + app.strips[i].leds; return st; });
			applyStrips();
		}
		adoptMask(j.mask || 0);
		takeState(j);
		app.dirty = false;
		buildTabs();
		renderPanel();
		updateDirty();
	}

	async function connectDevice(base) {
		const prev = app.device;
		app.device = base;
		app.probing = true;
		const j = await api('GET', '/json/held', null, 2500);
		app.probing = false;
		if (!j || j.v === undefined) { app.device = prev; return false; }
		app.online = true;
		takeFull(j);
		openWs();
		updateBadge();
		return true;
	}

	function disconnect() {
		app.device = null;
		if (app.ws) { app.ws.onclose = null; app.ws.close(); app.ws = null; }
		app.live = false;
		loadSim();
		updateBadge();
		buildTabs();
		renderPanel();
	}

	async function poll() {
		if (app.device !== null && !document.hidden && !app.pending) {
			const j = await api('GET', '/json/held?s');
			if (j && j.v !== undefined) takeState(j);
		}
		setTimeout(poll, POLL_MS);
	}

	// WLED live view: binary frames 'L', version, then RGB triplets for every LED
	function openWs() {
		if (app.ws) { app.ws.onclose = null; app.ws.close(); }
		let host = location.host;
		if (app.device) { try { host = new URL(app.device).host; } catch (e) { return; } }
		if (!host) return;
		let ws;
		try { ws = new WebSocket((location.protocol === 'https:' ? 'wss://' : 'ws://') + host + '/ws'); } catch (e) { return; }
		ws.binaryType = 'arraybuffer';
		app.ws = ws;
		ws.onopen = () => {
			ws.send('{"lv":true}');
			if (!app.liveChosen) app.live = true;
			updateSrc();
			updateBadge();
		};
		ws.onmessage = (e) => {
			if (typeof e.data === 'string') {
				try { const j = JSON.parse(e.data); if (j.state && j.state.bri !== undefined) { app.bri = j.state.bri; $('bri').value = j.state.bri; } } catch (x) { /* not JSON */ }
				return;
			}
			const d = new Uint8Array(e.data);
			if (d[0] !== 76 || d[1] !== 1) return;   // 'L', 1D format
			const n = (d.length - 2) / 3;
			app.strips.forEach((st, s) => {
				let b = app.liveBufs[s];
				if (!b || b.length !== 3 * st.leds) b = app.liveBufs[s] = new Float32Array(3 * st.leds);
				const start = app.starts[s] || 0;
				for (let i = 0; i < st.leds; i++) {
					const k = start + i;
					if (k >= n) { b[3 * i] = b[3 * i + 1] = b[3 * i + 2] = 0; continue; }
					b[3 * i] = d[2 + 3 * k] / 255; b[3 * i + 1] = d[3 + 3 * k] / 255; b[3 * i + 2] = d[4 + 3 * k] / 255;
				}
			});
			app.liveAt = performance.now();
		};
		ws.onclose = () => {
			app.ws = null;
			app.live = false;
			updateSrc();
			updateBadge();
			if (app.device !== null) setTimeout(() => { if (app.device !== null && !app.ws) openWs(); }, 3000);
		};
	}

	function updateSrc() {
		const b = $('srcBtn');
		b.textContent = app.live ? 'Live' : 'Mirror';
		b.classList.toggle('on', app.live);
		b.title = app.live ? 'Showing the device\'s actual LED output (tap for the local mirror)' : 'Showing the local mirror of the device (tap for live LEDs)';
	}

	// ------------------------------------------------------------------ simulator persistence
	function saveSim() {
		if (app.device !== null) return;
		try { localStorage.setItem(SIM_KEY, JSON.stringify({ params: exportParams(), strips: app.strips, bri: app.bri })); } catch (e) { /* storage unavailable */ }
	}

	function loadSim() {
		eng.params = S.defaults();
		app.strips = [S.defaultStrip(0)];
		try {
			const j = JSON.parse(localStorage.getItem(SIM_KEY) || 'null');
			if (j) {
				eng.setParams(j.params);
				if (j.strips && j.strips.length) app.strips = j.strips.slice(0, MAX_STRIPS).map((s, i) => HeldEngine.sanitizeStrip(s, i));
				if (j.bri) { app.bri = j.bri; $('bri').value = j.bri; }
			}
		} catch (e) { /* ignore bad storage */ }
		eng.setParams({});
		applyStrips();
		app.dirty = false;
		updateDirty();
	}

	function changed() {
		app.dirty = true;
		updateDirty();
		saveSim();
	}

	function updateDirty() { $('saveBtn').classList.toggle('dirty', app.dirty && app.device !== null); }

	// ------------------------------------------------------------------ actions
	function setParam(group, key, value) {
		eng.setParams({ [group]: { [key]: value } });
		const def = defsOf(group).find((d) => d.k === key);
		queueParams({ [group]: { [key]: def && def.t === 'c' ? hex(value) : value } });
		changed();
		if (group === 'global' && key === 'numPieces') { renderPieces(); renderPanel(); }
	}

	function applyStrips() {
		eng.setStrips(app.strips);
		view.setStrips(app.strips);
	}

	function setStrip(i, key, value) {
		app.strips[i][key] = value;
		app.strips[i] = HeldEngine.sanitizeStrip(app.strips[i], i);
		applyStrips();
		if (app.device !== null) send({ strips: app.strips.map((s) => { const o = Object.assign({}, s); delete o.leds; return o; }) });
		changed();
	}

	function setPieces(mask) {
		eng.setPieces(mask);
		send({ mask: eng.mask });
		renderPieces();
	}

	function trigger(type) {
		eng.trigger(type);
		send({ trigger: type });
	}

	// ------------------------------------------------------------------ UI: pieces & transport
	function renderPieces() {
		const box = $('pieces'), np = eng.params.global.numPieces;
		if (box.children.length !== np) {
			box.innerHTML = '';
			for (let i = 0; i < np; i++) {
				const b = el('button', 'piece', String(i + 1));
				b.onclick = () => setPieces(eng.mask ^ (1 << i));
				box.appendChild(b);
			}
		}
		for (let i = 0; i < np; i++) box.children[i].classList.toggle('in', !!(eng.mask & (1 << i)));
		$('pcTxt').textContent = eng.count + ' / ' + np + ' held';
	}

	function updateTransport() {
		$('play').textContent = app.playing ? '❚❚' : '▶';
		$('speed').value = String(app.timeScale);
	}

	// ------------------------------------------------------------------ UI: parameter controls
	function control(group, def, onSet) {
		const box = el('div', 'prm');
		const head = el('div', 'ph');
		const lab = el('span', 'lab', def.l + (def.u ? ' (' + def.u + ')' : ''));
		head.appendChild(lab);
		box.appendChild(head);
		if (def.h) {
			box.appendChild(el('div', 'help', def.h));
			lab.title = def.h;
			lab.onclick = () => box.classList.toggle('showhelp');
		}
		const get = () => (group === null ? def._get() : eng.params[group][def.k]);
		const set = onSet || ((v) => setParam(group, def.k, v));

		if (def.t === 'b') {
			const t = el('button', 'tog' + (get() ? ' on' : ''));
			t.onclick = () => { const v = get() ? 0 : 1; t.classList.toggle('on', !!v); set(v); };
			if (def.ro) t.disabled = true;
			head.appendChild(t);
			return box;
		}
		if (def.t === 'e') {
			const seg = el('div', 'seg');
			def.o.forEach((name, i) => {
				const b = el('button', get() === i ? 'sel' : '', name);
				b.onclick = () => { [...seg.children].forEach((c, k) => c.classList.toggle('sel', k === i)); set(i); };
				seg.appendChild(b);
			});
			box.appendChild(seg);
			return box;
		}
		if (def.t === 'c') {
			const c = el('input');
			c.type = 'color';
			c.value = hex(get());
			c.oninput = () => set(parseInt(c.value.slice(1), 16));
			head.appendChild(c);
			return box;
		}

		// numeric: a value, a [start, end] pair following the piece level, or an expression
		const ranged = () => Array.isArray(get());
		const isExpr = () => typeof get() === 'string';
		const step = def.s || (def.t === 'i' ? 1 : 0.01);
		const rebuild = () => box.replaceWith(control(group, def, onSet));
		if (group !== null && group !== 'global') {
			const now = el('span', 'now');
			head.appendChild(now);
			app.nowEls.push({ el: now, group: group, def: def });
			const fb = el('button', 'rng' + (isExpr() ? ' on' : ''), 'ƒ');
			fb.title = 'Expression: compute this value from pieces, time and event time';
			fb.onclick = () => {
				const v = get();
				if (typeof v === 'string') {
					const cur = eng.R[group][def.k];
					set(Number((Math.round(cur / step) * step).toFixed(4)));
				} else {
					set(EXPR_HEAD + (Array.isArray(v) ? `lerp(${v[0]}, ${v[1]}, level)` : String(v)));
				}
				rebuild();
			};
			head.appendChild(fb);
			if (!isExpr()) {
				const rb = el('button', 'rng' + (ranged() ? ' on' : ''), '⇆');
				rb.title = 'Follow the piece level: separate values for 0 pieces and for all-but-one pieces';
				rb.onclick = () => {
					const v = get();
					set(Array.isArray(v) ? v[0] : [v, v]);
					rebuild();
				};
				head.appendChild(rb);
			}
		}
		if (isExpr()) {
			const ta = el('textarea', 'code');
			ta.value = get();
			ta.rows = Math.min(10, Math.max(2, ta.value.split('\n').length));
			ta.spellcheck = false;
			ta.maxLength = HeldExpr.MAX_SRC;
			const msg = el('div', 'exprMsg'), errTxt = el('span');
			msg.appendChild(errTxt);
			const check = () => {
				const c = HeldExpr.compile(ta.value);
				ta.classList.toggle('bad', !!c.error);
				errTxt.textContent = c.error || '';
				if (!c.error && ta.value !== get()) set(ta.value);
			};
			let tm = 0;
			ta.oninput = () => {
				ta.rows = Math.min(10, Math.max(2, ta.value.split('\n').length));
				clearTimeout(tm);
				tm = setTimeout(check, 250);
			};
			box.appendChild(ta);
			box.appendChild(msg);
			const hint = el('div', 'help exprHelp');
			hint.textContent = 'Inputs: pieces, t (s), et (event age s, events only), level (0–1), numPieces. ' +
				'Functions: ' + HeldExpr.FUNCTIONS.join(' ') + '. Constants: PI TAU E. ' +
				'Use an expression or { let x = …; return …; }. Results are clamped to ' + def.min + '…' + def.max + '.';
			box.appendChild(hint);
			const hb = el('button', 'link', 'help');
			hb.onclick = () => box.classList.toggle('showhelp');
			msg.appendChild(hb);
			return box;
		}
		const np = eng.params.global.numPieces;
		const mkRow = (tag, idx) => {
			const row = el('div', 'sl');
			if (tag) row.appendChild(el('span', 'tag', tag));
			const r = el('input'), n = el('input');
			r.type = 'range'; n.type = 'number';
			r.min = n.min = def.min; r.max = n.max = def.max; r.step = n.step = step;
			if (def.ro) r.disabled = n.disabled = true;
			const cur = () => { const v = get(); return Array.isArray(v) ? v[idx] : v; };
			r.value = cur(); n.value = fmt(cur(), def);
			const apply = (x) => {
				x = Math.max(def.min, Math.min(def.max, Number(x)));
				if (!isFinite(x)) return;
				const v = get();
				let nv;
				if (Array.isArray(v)) { nv = v.slice(); nv[idx] = x; } else nv = x;
				set(nv);
			};
			r.oninput = () => { n.value = fmt(Number(r.value), def); apply(r.value); };
			n.onchange = () => { r.value = n.value; apply(n.value); };
			row.appendChild(r);
			row.appendChild(n);
			return row;
		};
		if (ranged()) {
			box.appendChild(mkRow('0 pcs', 0));
			box.appendChild(mkRow((np - 1) + ' pcs', 1));
		} else {
			box.appendChild(mkRow('', 0));
		}
		return box;
	}

	// Top-level tabs; "Pattern config" holds one sub-tab per layer (app.tab is the layer key then).
	const TABS = [{ k: 'pattern', l: 'Pattern config' }, { k: 'strips', l: 'Strip config' }, { k: 'setup', l: 'Setup' }];
	const tabGroup = () => (S.layerByKey[app.tab] ? 'pattern' : app.tab);

	function buildTabs() {
		const nav = $('tabs');
		nav.innerHTML = '';
		for (const t of TABS) {
			const b = el('button', t.k === tabGroup() ? 'sel' : '', t.l);
			b.onclick = () => {
				if (S.layerByKey[app.tab]) app.layerTab = app.tab;
				app.tab = t.k === 'pattern' ? (app.layerTab || S.layers[0].k) : t.k;
				buildTabs();
				renderPanel();
			};
			nav.appendChild(b);
		}
	}

	function renderPanel() {
		const p = $('panel');
		p.innerHTML = '';
		app.nowEls = [];
		if (app.tab === 'strips') return renderStrips(p);
		if (app.tab === 'setup') return renderSetup(p);
		const sub = el('nav', 'subtabs');
		for (const L of S.layers) {
			const b = el('button', L.k === app.tab ? 'sel' : '', L.l);
			b.onclick = () => { app.tab = app.layerTab = L.k; renderPanel(); };
			sub.appendChild(b);
		}
		p.appendChild(sub);
		const L = S.layerByKey[app.tab];
		p.appendChild(el('p', 'lhelp', L.h));
		let grp = null;
		for (const def of L.p) {
			if ((def.g || null) !== grp) { grp = def.g || null; if (grp) p.appendChild(el('h4', '', grp)); }
			p.appendChild(control(L.k, def));
		}
		const tools = el('div', 'layerTools');
		if (L.kind === 'event') {
			const tb = el('button', 'accent', 'Trigger ' + L.l.toLowerCase());
			tb.onclick = () => trigger(L.k);
			tools.appendChild(tb);
		}
		const rb = el('button', '', 'Reset ' + L.l.toLowerCase());
		rb.onclick = () => {
			const d = S.defaults()[L.k];
			eng.setParams({ [L.k]: d });
			queueParams({ [L.k]: exportParams()[L.k] });
			changed();
			renderPanel();
		};
		tools.appendChild(rb);
		p.appendChild(tools);
	}

	function renderStrips(p) {
		const dev = app.device !== null;
		p.appendChild(el('p', 'lhelp', dev
			? 'Strips are the WLED segments: one per LED output. LED counts, chipset and GPIO are set in LED settings. Tap an LED in the 3D view to find its index or make it the origin.'
			: 'Simulated strips. On a device each LED output becomes one strip. Tap an LED in the 3D view to find its index or make it the origin.'));
		app.strips.forEach((st, i) => {
			const card = el('div', 'stripCard');
			card.appendChild(el('h4', '', 'Strip ' + (i + 1)));
			let grp = null;
			for (const def0 of S.strip) {
				if ((def0.g || null) !== grp) { grp = def0.g || null; if (grp) card.appendChild(el('h4', '', grp)); }
				const def = Object.assign({}, def0, { _get: () => app.strips[i][def0.k] });
				if (def.k === 'origin') def.max = Math.max(0, st.leds - 1);
				if (def.k === 'leds' && dev) def.ro = true;
				card.appendChild(control(null, def, (v) => {
					setStrip(i, def.k, v);
					if (def.k === 'leds') renderPanel();
				}));
			}
			p.appendChild(card);
		});
		const row = el('div', 'row');
		if (dev) {
			const a = el('a', '', 'Open LED settings →');
			a.href = (app.device || '') + '/settings/leds';
			a.target = '_blank';
			row.appendChild(a);
		} else {
			const add = el('button', '', '+ Add strip'), rem = el('button', '', '− Remove strip');
			add.disabled = app.strips.length >= MAX_STRIPS;
			rem.disabled = app.strips.length <= 1;
			add.onclick = () => { app.strips.push(S.defaultStrip(app.strips.length)); applyStrips(); changed(); renderPanel(); };
			rem.onclick = () => { app.strips.pop(); applyStrips(); changed(); renderPanel(); };
			row.appendChild(add);
			row.appendChild(rem);
		}
		p.appendChild(row);
	}

	function renderSetup(p) {
		p.appendChild(el('h4', '', 'Pieces & level'));
		for (const def of S.global) p.appendChild(control('global', def));

		p.appendChild(el('h4', '', 'Connection'));
		if (app.device === null) {
			p.appendChild(el('p', 'lhelp', 'Running as a simulator. Enter a controller\'s address to drive it from here.'));
			const f = el('div', 'field');
			const ip = el('input');
			ip.type = 'text'; ip.placeholder = '192.168.4.1 or held.local';
			try { ip.value = localStorage.getItem(IP_KEY) || ''; } catch (e) { /* no storage */ }
			const b = el('button', 'accent', 'Connect');
			b.onclick = async () => {
				const v = ip.value.trim();
				if (!v) return;
				const base = /^https?:\/\//.test(v) ? v.replace(/\/$/, '') : 'http://' + v;
				b.disabled = true;
				const ok = await connectDevice(base);
				b.disabled = false;
				if (ok) { try { localStorage.setItem(IP_KEY, v); } catch (e) { /* no storage */ } toast('Connected'); renderPanel(); }
				else toast('No Held controller answered at ' + v);
			};
			f.appendChild(ip);
			f.appendChild(b);
			p.appendChild(f);
		} else {
			p.appendChild(el('p', 'lhelp', 'Connected to ' + (app.device || location.host) + '.'));
			const auto = control(null, { k: 'autoApply', t: 'b', l: 'Held drives all LEDs', h: 'Keep every segment on the Held effect. Turn off to use the classic WLED effects for testing wiring.', _get: () => (app.autoApply ? 1 : 0) },
				(v) => { app.autoApply = !!v; send({ autoApply: !!v }); app.dirty = true; updateDirty(); });
			p.appendChild(auto);
			const row = el('div', 'row');
			if (app.device) {
				const b = el('button', '', 'Disconnect (back to simulator)');
				b.onclick = disconnect;
				row.appendChild(b);
			}
			p.appendChild(row);
			const links = el('p', 'links');
			const base = app.device || '';
			[['WiFi', '/settings/wifi'], ['LEDs', '/settings/leds'], ['All settings', '/settings'], ['Classic WLED UI', '/classic'], ['Update firmware', '/update']].forEach(([t, h]) => {
				const a = el('a', '', t); a.href = base + h; a.target = '_blank'; links.appendChild(a);
			});
			p.appendChild(links);
		}

		p.appendChild(el('h4', '', 'Defaults'));
		const d = el('button', '', 'Reset every parameter to defaults');
		d.onclick = () => {
			if (!confirm('Reset all pattern parameters and strip placement to defaults?')) return;
			eng.params = S.defaults();
			eng.setParams({});
			if (app.device === null) { app.strips = app.strips.map((s, i) => Object.assign(S.defaultStrip(i), { leds: s.leds })); applyStrips(); }
			send({ defaults: true }).then(() => { if (app.device !== null) api('GET', '/json/held').then((j) => j && takeFull(j)); });
			changed();
			renderPieces();
			renderPanel();
		};
		p.appendChild(d);
	}

	// ------------------------------------------------------------------ status
	function updateStatus() {
		const dev = app.device !== null && app.devState;
		const level = dev ? app.devState.level : eng.level;
		$('lvlBar').style.width = (level * 100).toFixed(1) + '%';
		$('lvlTxt').textContent = level.toFixed(2);
		const H = eng.R.heartbeat;
		$('readout').textContent = `${H.bpm.toFixed(1)} BPM · pulses ${H.pulseSpeed.toFixed(1)} LED/s · baseline ${H.brightness.toFixed(2)}`;
		for (const n of app.nowEls) n.el.textContent = fmt(eng.R[n.group][n.def.k], n.def);
		const box = $('evList');
		let evs = eng.state().events;
		if (dev && app.live) {
			const lag = (performance.now() - app.devStateAt) / 1000 * (app.playing ? app.timeScale : 0);
			evs = (app.devState.events || []).map((e) => ({ type: e.t, age: e.age + lag, dur: e.dur })).filter((e) => e.age < e.dur);
		}
		box.innerHTML = '';
		for (const e of evs) {
			const L = S.layerByKey[e.type];
			const c = el('span', 'ev', L ? L.l : e.type);
			const bar = el('i');
			bar.style.width = Math.min(100, 100 * e.age / e.dur).toFixed(0) + '%';
			c.appendChild(bar);
			box.appendChild(c);
		}
		if (!evs.length) box.appendChild(el('span', 'muted small', 'no events running'));
	}

	// ------------------------------------------------------------------ render loop
	const bufs = [];
	let last = performance.now(), lastStatus = 0, lastRow = 0;
	function frame(now) {
		const dt = Math.min(0.1, (now - last) / 1000);
		last = now;
		if (app.playing) eng.tick(dt * app.timeScale);
		let cols;
		const liveFresh = app.live && app.ws && app.liveAt && now - app.liveAt < 1500;
		if (liveFresh) cols = app.liveBufs;
		else {
			cols = app.strips.map((st, i) => {
				if (!bufs[i] || bufs[i].length !== 3 * st.leds) bufs[i] = new Float32Array(3 * st.leds);
				eng.render(i, bufs[i]);
				return bufs[i];
			});
		}
		// LED brightness is linear in PWM after gamma; on screen that reads roughly as bri^(1/2.2)
		const gain = Math.pow(app.bri / 255, 1 / 2.2);
		view.draw(cols, gain, dt);
		if (now - lastRow >= 33) { lastRow = now; kymo.push(cols, gain); }  // ~30 rows/s: ~3.5 s of history
		if (now - lastStatus > 150) { lastStatus = now; updateStatus(); }
		requestAnimationFrame(frame);
	}

	// ------------------------------------------------------------------ wiring
	function wire() {
		$('play').onclick = () => { app.playing = !app.playing; updateTransport(); send({ play: app.playing }); };
		$('speed').onchange = () => { app.timeScale = Number($('speed').value); send({ timeScale: app.timeScale }); };
		$('bri').oninput = () => {
			app.bri = Number($('bri').value);
			clearTimeout(wire.briTm);
			if (app.device !== null) wire.briTm = setTimeout(() => api('POST', '/json/state', { bri: app.bri }), 80);
			else saveSim();
		};
		$('allInBtn').onclick = () => setPieces((1 << eng.params.global.numPieces) - 1);
		$('allOutBtn').onclick = () => setPieces(0);
		$('clearEv').onclick = () => { eng.clearEvents(); send({ clear: true }); };
		document.querySelectorAll('[data-trig]').forEach((b) => { b.onclick = () => trigger(b.dataset.trig); });

		const chip = (id, prop) => {
			const b = $(id);
			b.onclick = () => { view[prop] = !view[prop]; b.classList.toggle('on', view[prop]); };
		};
		chip('rotBtn', 'autoRotate');
		chip('glowBtn', 'glow');
		chip('shellBtn', 'shell');
		view.onChange = (what) => { if (what === 'rotate') $('rotBtn').classList.remove('on'); };
		$('frontBtn').onclick = () => { view.resetView(); view.autoRotate = false; $('rotBtn').classList.remove('on'); };
		$('srcBtn').onclick = () => { app.live = !app.live; app.liveChosen = true; updateSrc(); };

		view.onPick = (s, i) => {
			const box = $('pick');
			view.highlight = s >= 0 ? { s: s, i: i } : null;
			if (s < 0) { box.hidden = true; return; }
			box.innerHTML = '';
			box.appendChild(el('span', '', 'Strip ' + (s + 1) + ' · LED ' + i));
			const b = el('button', '', 'Set as origin');
			b.onclick = () => { setStrip(s, 'origin', i); box.hidden = true; view.highlight = null; if (app.tab === 'strips') renderPanel(); toast('Strip ' + (s + 1) + ' origin set to LED ' + i); };
			box.appendChild(b);
			box.hidden = false;
		};

		$('saveBtn').onclick = async () => {
			if (app.device === null) { saveSim(); app.dirty = false; updateDirty(); toast('Saved in this browser'); return; }
			if (app.pending) { clearTimeout(app.pendingTimer); const p = app.pending; app.pending = null; await send({ params: p }); }
			const j = await send({ save: true });
			if (j) { app.dirty = false; updateDirty(); toast('Saved to device'); }
		};
		$('revertBtn').onclick = async () => {
			if (app.device === null) { loadSim(); renderPieces(); renderPanel(); toast('Reloaded browser settings'); return; }
			const j = await api('GET', '/json/held');
			if (j) { takeFull(j); toast('Reloaded from device'); }
		};
		$('exportBtn').onclick = () => {
			const data = { held: S.version, params: exportParams(), strips: app.strips };
			const a = el('a');
			a.href = URL.createObjectURL(new Blob([JSON.stringify(data, null, 1)], { type: 'application/json' }));
			a.download = 'held-settings.json';
			a.click();
			setTimeout(() => URL.revokeObjectURL(a.href), 1000);
		};
		$('importBtn').onclick = () => $('importFile').click();
		$('importFile').onchange = async () => {
			const f = $('importFile').files[0];
			$('importFile').value = '';
			if (!f) return;
			try {
				const j = JSON.parse(await f.text());
				if (j.params) eng.setParams(j.params);
				if (j.strips && j.strips.length) {
					if (app.device === null) app.strips = j.strips.slice(0, MAX_STRIPS).map((s, i) => HeldEngine.sanitizeStrip(s, i));
					else app.strips = app.strips.map((s, i) => Object.assign(HeldEngine.sanitizeStrip(j.strips[i] || s, i), { leds: s.leds }));
					applyStrips();
				}
				await send({ params: exportParams(), strips: app.strips.map((s) => { const o = Object.assign({}, s); delete o.leds; return o; }) });
				changed();
				renderPieces();
				renderPanel();
				toast('Imported ' + f.name);
			} catch (e) {
				toast('Could not read that file');
			}
		};
		document.addEventListener('visibilitychange', () => { last = performance.now(); });
	}

	async function start() {
		wire();
		loadSim();
		updateTransport();
		buildTabs();
		renderPanel();
		renderPieces();
		updateBadge();
		requestAnimationFrame(frame);
		if (window.HeldViewGL) HeldViewGL.upgrade(view).then((v) => { if (v) view = v; });

		// device detection: ?ip=..., then same origin (served by the controller or the dev proxy)
		const qp = new URLSearchParams(location.search).get('ip');
		let ok = false;
		if (qp) ok = await connectDevice(/^https?:\/\//.test(qp) ? qp : 'http://' + qp);
		if (!ok && /^https?:$/.test(location.protocol) && !new URLSearchParams(location.search).has('sim')) ok = await connectDevice('');
		if (ok) toast('Connected to Held controller');
		poll();
	}

	start();
})();
// AI: end
